#include <bits/stdc++.h>
using namespace std;

const int INF=10000000;
const int N=210;
const int M=21000;

struct Edge {
    int v,w;
};

vector<int> adj[N];
Edge edges[M];
int head[N],e;

void add_edge(int u,int v,int w){
    edges[e]={v,w};
    adj[u].push_back(e++);
    edges[e]={u,0};
    adj[v].push_back(e++);
}

int S,T;
int dist[N],q[N*2],arc[N],gap[N],inq[N],pre[N];

int max_flow(int s,int t){
    memset(arc,-1,sizeof(arc));
    memset(pre,-1,sizeof(pre));
    int front=0,rear=0;
    q[rear++]=t; inq[t]=1; gap[0]++;
    dist[t]=0;
    while(front<rear){
        int u=q[front++];
        for(auto i:adj[u]){
            int v=edges[i].v;
            if(!inq[v]){
                q[rear++]=v;
                inq[v]=1;
                dist[v]=dist[u]+1;
                gap[dist[v]]++;
                arc[v]=i;
            }
        }
    }
    int flow=0, u=s, low=INF;
    memset(pre,-1,sizeof(pre));
    pre[s]=s;
    while(dist[s]<t){
        bool pushed=false;
        for(int &i=arc[u];i!=-1;i=adj[u][i]){
            if(edges[i].w && dist[edges[i].v]+1==dist[u]){
                pushed=true;
                low=min(low,edges[i].w);
                pre[edges[i].v]=u;
                u=edges[i].v;
                if(u==t){
                    int delta=low;
                    while(u!=s){
                        int i=pre[u];
                        edges[i].w-=delta;
                        edges[i^1].w+=delta;
                        u=pre[u];
                    }
                    flow+=delta;
                    low=INF;
                }
                break;
            }
        }
        if(pushed) continue;
        int minDist=t+1;
        for(auto i:adj[u]){
            int v=edges[i].v;
            if(edges[i].w && dist[v]<minDist){
                minDist=dist[v];
                arc[u]=i;
            }
        }
        gap[dist[u]]--;
        if(gap[dist[u]]==0) break;
        dist[u]=minDist+1;
        gap[dist[u]]++;
        u=pre[u];
    }
    return flow;
}

char grid1[12][12], grid2[12][12];
int sci[12][12], ca[12][12], stone[62][12][12];
int dp[62][12][12][12][12];
int dir[4][2]={{-1,0},{1,0},{0,-1},{0,1}};
int n,t;

void expand(){
    for(int k=1;k<=t;++k)
        for(int i=1;i<=n;++i)
            for(int j=1;j<=n;++j){
                if(stone[k-1][i][j]==1)
                    stone[k][i][j]=1;
                else if(stone[k-1][i][j]==2)
                    stone[k][i][j]=2;
                else{
                    for(int z=0;z<4;++z){
                        int nx=i+dir[z][0], ny=j+dir[z][1];
                        if(nx>=1 && nx<=n && ny>=1 && ny<=n){
                            if(stone[k-1][nx][ny]==2)
                                stone[k][i][j]=2;
                        }
                    }
                }
            }
}

int visited[12][12];

void dfs(int x,int y,int nowx,int nowy,int k){
    visited[nowx][nowy]=1;
    dp[k][x][y][nowx][nowy]=1;
    if(k>=t || stone[k][nowx][nowy]) return;
    for(int z=0; z<4; ++z){
        int nx=nowx+dir[z][0], ny=nowy+dir[z][1];
        if(nx>=1 && nx<=n && ny>=1 && ny<=n && !visited[nx][ny]){
            if(stone[k][nx][ny]) continue;
            dfs(x,y,nx,ny,k+1);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> t;
    for(int i=1; i<=n; ++i){
        cin >> (grid1[i]+1);
        for(int j=1; j<=n; ++j){
            if(grid1[i][j]=='Z') stone[0][i][j]=2;
            else if(grid1[i][j]=='Y') stone[0][i][j]=1;
            else sci[i][j]=grid1[i][j]-'0';
        }
    }
    for(int i=1; i<=n; ++i){
        cin >> (grid2[i]+1);
        for(int j=1; j<=n; ++j){
            if(grid2[i][j]>='0' && grid2[i][j]<='9') ca[i][j]=grid2[i][j]-'0';
        }
    }
    expand();
    for(int i=1; i<=n; ++i)
        for(int j=1; j<=n; ++j)
            if(sci[i][j]){
                memset(visited,0,sizeof(visited));
                dfs(i,j,i,j,0);
            }
    for(int k=1; k<=t; ++k)
        for(int x=1; x<=n; ++x)
            for(int y=1; y<=n; ++y)
                for(int nx=1; nx<=n; ++nx)
                    for(int ny=1; ny<=n; ++ny)
                        dp[k][x][y][nx][ny]+=dp[k-1][x][y][nx][ny];

    int S=0, T=n*n*2+1;
    for(int i=0; i<=T; ++i) adj[i].clear();
    for(int i=1; i<=n; ++i)
        for(int j=1; j<=n; ++j)
            add_edge(S, (i-1)*n+j, sci[i][j]);
    for(int i=1; i<=n; ++i)
        for(int j=1; j<=n; ++j)
            add_edge(n*n+(i-1)*n+j, T, ca[i][j]);
    for(int x=1; x<=n; ++x)
        for(int y=1; y<=n; ++y)
            for(int nx=1; nx<=n; ++nx)
                for(int ny=1; ny<=n; ++ny)
                    if(sci[x][y] && ca[nx][ny]){
                        if(dp[t][x][y][nx][ny])
                            add_edge((x-1)*n+y, n*n+(nx-1)*n+ny, INF);
                    }
    int ans=max_flow(S,T);
    cout << ans << "\n";
    return 0;
}
